-- Karachi Bites Supabase Schema & Seed Script
-- Run this in your Supabase SQL Editor (https://supabase.com/dashboard/project/bcresoluaayogaqfadot/sql)

CREATE TABLE IF NOT EXISTS public.menu (
  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  price NUMERIC NOT NULL,
  tags TEXT DEFAULT 'mild',
  available BOOLEAN DEFAULT true,
  description TEXT,
  image TEXT,
  portion TEXT,
  spice_level TEXT,
  created_at TIMESTAMPTZ DEFAULT now()
);

-- Enable public read access (Row Level Security)
ALTER TABLE public.menu ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Allow public read access to menu" ON public.menu;
CREATE POLICY "Allow public read access to menu" ON public.menu FOR SELECT USING (true);

